  if (import.meta.env.MODE === 'production') {
    return <></>
  }

  return (
    <Menu>
      <MenuButton
        position="absolute"
        top={0}
        right={0}
        size={'xs'}
        variant="ghost"
        colorScheme="error"
        as={IconButton}
        aria-label="Dev User Switch"
        icon={<RiLoginCircleLine />}
        zIndex={100}
      />
      <Portal>
        <MenuList>
          <MenuItem onClick={auth.logOut}>Public/Logout</MenuItem>
          {[
            'tenantVisitor',
            'tenantMember',
            'tenantTeamMember',
            'tenantTeamLead',
            'tenantAdmin',
            'superadmin',
            'anotherAdmin',
            'inactiveAdmin',
          ].map((user) => {
            return (
              <MenuItem
                key={user}
                onClick={() => {
                  auth.logIn({
                    email: `${user}@buildplace.io`,
                    password: import.meta.env.WEBAPP_DEV_USER_PW,
                  })
                }}
              >
                {user}
              </MenuItem>
            )
          })}
        </MenuList>
      </Portal>
    </Menu>
  )
}
export default DevUserSwitch

